 typeset -g __nauterm_ai_armed=0; typeset -g __nauterm_command_active=0; typeset -g __nauterm_ai_token='{{TOKEN}}'; function __nauterm_command_preexec() { local __nauterm_command_encoded; __nauterm_command_encoded=$(printf '%s' "$1" | command base64 2>/dev/null | command tr -d '\r\n'); printf '\033]4545;CommandStarted;%s;%s\007\033]133;C;aid=%s\007' "$$" "$__nauterm_command_encoded" "$$"; __nauterm_command_active=1; }; function __nauterm_ai_precmd() { local __nauterm_ai_status=$?; if [[ ${__nauterm_command_active:-0} -eq 1 ]]; then printf '\033]4545;CommandExited;%s;%s\007\033]133;D;%s;aid=%s\007' "$$" "$__nauterm_ai_status" "$__nauterm_ai_status" "$$"; __nauterm_command_active=0; fi; if [[ ${__nauterm_ai_armed:-0} -eq 1 ]]; then printf '\033]777;nauterm-command-end=%s;%s\007' "$__nauterm_ai_token" "$__nauterm_ai_status"; __nauterm_ai_armed=0; fi; printf '\033]7;file://localhost%s\007\033]133;A\007' "$PWD"; }; function __nauterm_line_init() { printf '\033]133;B\007'; }; function __nauterm_ai_park_line() { if [[ -n "$BUFFER" ]]; then zle -I; print -r -- ''; BUFFER=''; CURSOR=0; fi; __nauterm_ai_armed=1; printf '\033]777;nauterm-line-ready=%s\007' "$__nauterm_ai_token"; }; autoload -Uz add-zsh-hook add-zle-hook-widget; add-zsh-hook -d preexec __nauterm_command_preexec 2>/dev/null; add-zsh-hook preexec __nauterm_command_preexec; add-zsh-hook -d precmd __nauterm_ai_precmd 2>/dev/null; add-zsh-hook precmd __nauterm_ai_precmd; add-zle-hook-widget -d line-init __nauterm_line_init 2>/dev/null; add-zle-hook-widget line-init __nauterm_line_init; zle -N __nauterm_ai_park_line; bindkey '^X^]' __nauterm_ai_park_line; {{READY}}